  UNIQUE(request_id, equipment_id)
);
CREATE TABLE IF NOT EXISTS time_windows (
  id INTEGER PRIMARY KEY, request_id INTEGER NOT NULL REFERENCES requests(id) ON DELETE CASCADE,
