            (token_hash(token), user["id"], now_epoch() + SESSION_SECONDS, now_epoch()),
        )
        db.connection.commit()
        return self.send_json(200, {"user": safe}, {"Set-Cookie": cookie_header(token, SESSION_SECONDS)})

