const apiReady = window.mlmApi ? Promise.resolve() : new Promise(resolve => { const s = document.createElement('script'); s.src = '../js/api.js'; s.onload = resolve; document.head.appendChild(s); });
apiReady.then(async () => {
  let category = 'All';
  const $ = selector => document.querySelector(selector);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
  const cart = () => JSON.parse(localStorage.getItem('mlmCart') || '[]');
  const draw = async () => {
    const filters = { q: $('#search').value, limit: 1000 };
    if ($('#available').checked) filters.status = 'available';
    try {
      const result = await mlmApi.equipment(filters);
      const items = Array.isArray(result) ? result : (result.equipment || result.items || []);
      const selected = [...document.querySelectorAll('.brand-filter:checked')].map(x => x.value.toLowerCase());
      const list = items.filter(x => (!category || category === 'All' || (x.category || '').toLowerCase() === category.toLowerCase()) && (!selected.length || selected.includes(String(x.brand || '').toLowerCase())));
      const selectedIds = new Set(cart().map(x => Number(x.id)));
      $('#equipmentGrid').innerHTML = list.map(item => `<article class="equipment-card"><div class="product-image">â–±</div><div class="product-info"><span class="tag">${esc(item.category || item.status || 'Equipment')}</span><span class="availability">â— ${esc(item.status || 'available')}</span><h3>${esc(item.name)}</h3><p>${esc(item.asset_code || item.assetCode || item.location || '')}</p><button class="${selectedIds.has(Number(item.id)) ? 'unavailable' : 'primary'}" ${selectedIds.has(Number(item.id)) ? 'disabled' : ''} data-add="${item.id}">${selectedIds.has(Number(item.id)) ? 'âœ“ Added to Cart' : 'ï¼‹ Add to Booking'}</button></div></article>`).join('') || '<p>No equipment matches these filters.</p>';
      $('#cartCount').textContent = cart().length;
      document.querySelectorAll('[data-add]').forEach(button => button.onclick = () => { const item = list.find(x => Number(x.id) === Number(button.dataset.add)); const next = cart(); if (item && !next.some(x => Number(x.id) === Number(item.id))) { next.push(item); localStorage.setItem('mlmCart', JSON.stringify(next)); draw(); } });
    } catch (error) { $('#equipmentGrid').innerHTML = '<p>Equipment is unavailable until the API is connected.</p>'; mlmUiError(error.message); }
  };
  $('#search').oninput = draw; $('#available').onchange = draw;
  document.querySelectorAll('.brand-filter').forEach(x => x.onchange = draw);
  document.querySelectorAll('[data-category]').forEach(x => x.onclick = () => { category = x.dataset.category; document.querySelectorAll('[data-category]').forEach(y => y.classList.toggle('selected', y === x)); draw(); });
  $('#clearFilters').onclick = () => { $('#search').value = ''; $('#available').checked = false; document.querySelectorAll('.brand-filter').forEach(x => x.checked = false); category = 'All'; draw(); };
  draw();
});
--- bookings ---
const bookingsApiReady = window.mlmApi ? Promise.resolve() : new Promise(resolve => { const s = document.createElement('script'); s.src = '../js/api.js'; s.onload = resolve; document.head.appendChild(s); });
bookingsApiReady.then(() => {
  const $ = selector => document.querySelector(selector); let cart = JSON.parse(localStorage.getItem('mlmCart') || '[]');
  const toast = message => { $('#toast').textContent = message; $('#toast').classList.add('show'); setTimeout(() => $('#toast').classList.remove('show'), 3000); };
  const draw = () => { $('#itemCount').textContent = `(${cart.length} Item${cart.length === 1 ? '' : 's'} Selected)`; $('#cartItems').innerHTML = cart.length ? cart.map(x => `<article class="cart-item"><div class="cart-thumb">â–±</div><div><span class="tag">${x.status || 'Equipment'}</span><h3>${x.name}</h3><p>Asset ${x.asset_code || x.assetCode || x.id}</p></div><button class="remove" data-id="${x.id}">Remove</button></article>`).join('') : '<article class="cart-item"><div><h3>Your booking cart is empty</h3><p>Return to the catalog to add equipment.</p></div></article>'; document.querySelectorAll('[data-id]').forEach(button => button.onclick = () => { cart = cart.filter(x => Number(x.id) !== Number(button.dataset.id)); localStorage.setItem('mlmCart', JSON.stringify(cart)); draw(); }); };
  $('#clearCart').onclick = () => { cart = []; localStorage.setItem('mlmCart', '[]'); draw(); };
