  if (document.querySelector('#requestList')) { try { const result = await mlmApi.requests('?status=pending'); const requests = Array.isArray(result) ? result : (result.requests || []); document.querySelector('#requestList').innerHTML = requests.map(x => `<article class="request-card"><div class="request-head"><div><h2>Request #${x.id}</h2><p>${esc(x.requester_name || x.requesterId || '')}</p></div><span class="status pending">pending</span></div><div class="request-details"><article><b>Equipment</b><p>${(x.items || []).map(i => esc(i.name || i.equipment_id)).join(', ')}</p></article><article><b>Purpose</b><p>${esc(x.purpose)}</p></article></div><div class="request-actions"><button class="reject" data-action="reject" data-id="${x.id}">Reject</button><button class="primary" data-action="approve" data-id="${x.id}">Approve</button></div></article>`).join('') || '<p>No pending requests.</p>'; document.querySelectorAll('[data-action]').forEach(button => button.onclick = async () => { try { if (button.dataset.action === 'approve') await mlmApi.approveRequest(button.dataset.id, actor()); else await mlmApi.rejectRequest(button.dataset.id, actor(), prompt('Reason for rejection') || ''); button.closest('.request-card').remove(); } catch (error) { mlmUiError(error.message); } }); } catch (error) { mlmUiError(error.message); } }
