    const notes = requests.flatMap(request => {
      const itemNames = (request.items || []).map(item => item.name || item.equipment_id).join(', ') || 'equipment';
      const pickup = request.windows?.find(window => window.kind === 'pickup');
      const message = `Request #${request.id} for ${itemNames} is ${request.status}.`;
      return [{ icon: request.status === 'approved' ? 'âœ“' : 'â€¢', title: `Request #${request.id} â€” ${request.status}`, message, action: request.status === 'approved' && pickup ? `<a class="primary" href="pickup-pass.html?booking=${request.id}">View Pickup Pass</a>` : '', time: request.updated_at || request.created_at }];
    });
    target.innerHTML = notes.map(note => `<article class="notice-card"><i class="notice-icon">${note.icon}</i><div><h2>${note.title}</h2><p>${note.message}</p>${note.action}<small>${note.time ? new Date(note.time).toLocaleString() : ''}</small></div></article>`).join('') || '<p>No notifications yet.</p>';
  } catch (error) { target.innerHTML = `<p>${error.message}</p>`; }
  document.querySelector('#readAll').onclick = event => { event.target.textContent = 'All caught up âœ“'; };
})();


---HISTORY---

const historyApiReady = window.mlmApi ? Promise.resolve() : new Promise(resolve => { const s = document.createElement('script'); s.src = '../js/api.js'; s.onload = resolve; document.head.appendChild(s); });
historyApiReady.then(() => window.mlmSessionReady).then(() => mlmSession.requireAuth()).then(async () => {
  const tbody = document.querySelector('#historyRows'); const user = mlmApi.currentUser();
  const format = value => value ? new Date(value).toLocaleString() : 'â€”';
  try {
    if (!user?.id) throw new Error('Sign in before viewing booking history.');
    const result = await mlmApi.requests(`?requesterId=${encodeURIComponent(user.id)}`); const rows = Array.isArray(result) ? result : (result.requests || []);
    tbody.innerHTML = rows.map(request => `<tr><td><b>${request.id}</b></td><td>${(request.items || []).map(item => item.name || item.equipment_id).join(', ')}</td><td>${format(request.windows?.find(x => x.kind === 'pickup')?.starts_at)}</td><td>${format(request.windows?.find(x => x.kind === 'return')?.ends_at)}</td><td><span class="status ${request.status}">${request.status}</span></td><td><a href="return.html?request=${request.id}">View Details</a> ${['approved','pickup_pending','picked_up'].includes(request.status) ? `<button class="extend" data-id="${request.id}">Extend</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="6">No requests found.</td></tr>';
    document.querySelectorAll('.extend').forEach(button => button.onclick = async () => { const startsAt = prompt('Requested extension start (ISO-8601)', new Date().toISOString()); const endsAt = prompt('Requested extension end (ISO-8601)'); if (!startsAt || !endsAt) return; try { await mlmApi.extension({ requestId: Number(button.dataset.id), startsAt, endsAt, actorId: Number(user.id), notes: 'Requested from booking history' }); alert('Extension request submitted.'); } catch (error) { mlmUiError(error.message); } });
  } catch (error) { tbody.innerHTML = `<tr><td colspan="6">${error.message}</td></tr>`; }
});


---BOOKINGS---

const bookingsApiReady = window.mlmApi ? Promise.resolve() : new Promise(resolve => { const s = document.createElement('script'); s.src = '../js/api.js'; s.onload = resolve; document.head.appendChild(s); });
bookingsApiReady.then(() => window.mlmSessionReady).then(() => mlmSession.requireAuth()).then(() => {
  const $ = selector => document.querySelector(selector); let cart = JSON.parse(localStorage.getItem('mlmCart') || '[]');
  const toast = message => { $('#toast').textContent = message; $('#toast').classList.add('show'); setTimeout(() => $('#toast').classList.remove('show'), 3000); };
  const draw = () => { $('#itemCount').textContent = `(${cart.length} Item${cart.length === 1 ? '' : 's'} Selected)`; $('#cartItems').innerHTML = cart.length ? cart.map(x => `<article class="cart-item"><div class="cart-thumb">â–±</div><div><span class="tag">${x.status || 'Equipment'}</span><h3>${x.name}</h3><p>Asset ${x.asset_code || x.assetCode || x.id}</p></div><button class="remove" data-id="${x.id}">Remove</button></article>`).join('') : '<article class="cart-item"><div><h3>Your booking cart is empty</h3><p>Return to the catalog to add equipment.</p></div></article>'; document.querySelectorAll('[data-id]').forEach(button => button.onclick = () => { cart = cart.filter(x => Number(x.id) !== Number(button.dataset.id)); localStorage.setItem('mlmCart', JSON.stringify(cart)); draw(); }); };
  $('#clearCart').onclick = () => { cart = []; localStorage.setItem('mlmCart', '[]'); draw(); };
  $('#submit').onclick = async () => { const user = mlmApi.currentUser(); const dates = document.querySelectorAll('input[type="datetime-local"]'); const pickup = new Date(dates[0].value); const returned = new Date(dates[1].value); if (!user?.id) return toast('Sign in with a backend user before submitting a request.'); if (!cart.length || Number.isNaN(pickup.getTime()) || Number.isNaN(returned.getTime()) || returned <= pickup) return toast('Choose valid pickup and return times.'); try { const result = await mlmApi.createRequest({ requesterId: Number(user.id), equipmentIds: cart.map(x => Number(x.id)), purpose: document.querySelector('select').value, pickupStartsAt: pickup.toISOString(), pickupEndsAt: new Date(pickup.getTime() + 60 * 60 * 1000).toISOString(), returnStartsAt: returned.toISOString(), returnEndsAt: new Date(returned.getTime() + 60 * 60 * 1000).toISOString() }); localStorage.setItem('mlmLastRequest', JSON.stringify(result)); localStorage.setItem('mlmCart', '[]'); location.href = 'history.html'; } catch (error) { toast(error.message); } };
  draw();
});


---ADMIN---

